import {ContractError,validDate} from './cloud-contract.mjs';
const fail=()=>{throw new ContractError('素材归档或内容改期资料不完整，请刷新。');};
const id=v=>{if(typeof v!=='string'||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(v))fail();return v;};
const int=(v,min=0)=>{if(!Number.isSafeInteger(v)||v<min||v>=2147483647)fail();return v;};
export const operationalKind=k=>{if(!['material-archive','task-schedule'].includes(k))fail();return k;};
export function operationalState(v,kind,owner){if(!v||v.kind!==kind||v.target?.id!==owner||typeof v.target.title!=='string'||!v.history||!Array.isArray(v.history.rows)||v.history.rows.length>50||v.history.limit!==50)fail();operationalKind(kind);id(v.target.id);int(v.history.total);int(v.history.offset);if(kind==='material-archive'){int(v.target.version,1);if(typeof v.target.archived!=='boolean')fail();}else{int(v.target.scheduleVersion);if(v.target.plannedPublishOn!==null&&!validDate(v.target.plannedPublishOn))fail();}
 for(const r of v.history.rows){id(r.id);int(r.version,1);if(typeof r.reason!=='string'||!r.reason.trim()||typeof r.actor!=='string'||!Number.isFinite(Date.parse(r.createdAt)))fail();if(kind==='material-archive'){if(typeof r.archived!=='boolean')fail();int(r.materialVersion,1);}else for(const k of ['plannedPublishOn','previousOn'])if(r[k]!==null&&!validDate(r[k]))fail();}return v;
}
export function operationalPayload(kind,v){operationalKind(kind);const keys=['requestKey','expectedVersion','reason',kind==='material-archive'?'archived':'plannedPublishOn'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||typeof v.reason!=='string'||!v.reason.trim()||v.reason.length>2000)fail();const out={requestKey:id(v.requestKey),expectedVersion:int(v.expectedVersion,kind==='material-archive'?1:0),reason:v.reason.trim()};if(kind==='material-archive'){if(typeof v.archived!=='boolean')fail();return {...out,archived:v.archived};}if(v.plannedPublishOn!==null&&!validDate(v.plannedPublishOn))fail();return {...out,plannedPublishOn:v.plannedPublishOn};}
export function createOperationalEditors({api,h,mount,input,area}){
 async function operationalChange(kind,owner){const s=await api.operationalState(kind,owner),r=s.target,key=crypto.randomUUID(),archive=kind==='material-archive';if(!archive&&!r.canReschedule)throw new Error('只能调整尚未结束的内容执行事项；拍摄使用原交付日期入口。');mount(archive?(r.archived?'恢复素材':'归档素材'):'调整内容执行日期',`<p>${h(r.title)}</p><p class="planning-rule">${archive?(r.archived?'恢复后重新进入在用素材和新参考选择。原引用、附件和历史保留。':'归档后从在用素材和新参考选择中隐藏。已安排的执行、原引用、附件及测试状态保留；不删除记录。'):'只调整当前执行事项，保留原轮次日期、同轮其他事项、已发布和已回填记录。留空表示未排期；实际发布日期不改变。'}</p>`+(archive?'':input('plannedPublishOn','新的执行日期（可留空）',r.plannedPublishOn||'','type="date"'))+area('reason',archive?'归档或恢复原因（必填）':'改期原因（必填）'),f=>api.saveOperationalChange(kind,owner,{requestKey:key,expectedVersion:archive?r.version:r.scheduleVersion,reason:f.get('reason'),...(archive?{archived:!r.archived}:{plannedPublishOn:f.get('plannedPublishOn')||null})}),{kind:'operational-change',operationKind:kind,id:owner},()=>api.operationalReceipt(kind,owner,key));
 }return {operationalChange};
}
export function createOperationalViews({api,h,showPanel,localTime,notify}){
 async function history(kind,owner,offset=0){await showPanel('归档与改期历史',async signal=>{const s=await api.operationalState(kind,owner,offset,signal),archive=kind==='material-archive';return `<div class="dialog-header"><h2>${archive?'素材归档与恢复':'执行事项改期'}历史</h2><button class="icon-button" data-operational-close aria-label="关闭历史">×</button></div><p>${h(s.target.title)}</p><p class="muted">${archive?'只改变素材是否在用，不重置测试状态或原引用。':'只影响此事项的执行日期，不改变原轮次或实际发布/回填时间。'}</p>${s.history.rows.map(r=>`<article class="observation"><b>第 ${r.version} 版 · ${archive?(r.archived?'已归档':'已恢复'):(h(r.previousOn||'未排期')+' → '+h(r.plannedPublishOn||'未排期'))}</b><p class="preserve-text">${h(r.reason)}</p><small>${h(r.actor)} · ${h(localTime(r.createdAt))}</small></article>`).join('')||'<p class="muted">尚无变更记录。</p>'}<div class="pager"><button class="secondary" data-operational-history="${kind}" data-id="${h(owner)}" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>上一页</button><span>${s.history.total} 条</span><button class="secondary" data-operational-history="${kind}" data-id="${h(owner)}" data-offset="${offset+50}" ${offset+50>=s.history.total?'disabled':''}>下一页</button></div>`;});}
 document.addEventListener('click',e=>{if(e.target.closest('[data-operational-close]'))document.querySelector('#cloud-detail').close();const b=e.target.closest('[data-operational-history]');if(b)history(b.dataset.operationalHistory,b.dataset.id,Number(b.dataset.offset||0)).catch(e=>notify(e.message));});return {history};
}
